add_action( 'init', 'perfectpixel_description_without_tabs_setup' );

function perfectpixel_description_without_tabs_setup() {
	remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_output_product_data_tabs', 10 );
	add_action( 'woocommerce_after_single_product_summary', 'perfectpixel_description_without_tabs', 10 );
}

function perfectpixel_description_without_tabs() {
	if ( '' === trim( (string) get_post_field( 'post_content', get_the_ID() ) ) ) {
		return;
	}
	echo '<div class="perfectpixel-product-description" style="clear:both;margin-bottom:2em">';
	$heading = trim( '{{description_section_heading}}' );
	if ( '' !== $heading ) {
		echo '<h2>' . esc_html( $heading ) . '</h2>';
	}
	the_content();
	echo '</div>';
}
